/** @description Proves the caller-visible display-name normalization contract. */

import { describe, expect, it } from 'vitest';

import { toDisplayName } from './index';

describe('toDisplayName', () => {
	it('normalizes whitespace and word casing', () => {
		expect(toDisplayName('  aDA   loveLACE ')).toBe('Ada Lovelace');
	});

	it('returns an empty string for whitespace-only input', () => {
		expect(toDisplayName('   ')).toBe('');
	});
});

/** @description Owns private, deterministic display-text normalization. */

/** @description Normalizes whitespace and title-cases each whitespace-separated word. */
export function toDisplayName(value: string): string {
	return value
		.trim()
		.split(/\s+/u)
		.filter((word) => word.length > 0)
		.map((word) => `${word.charAt(0).toUpperCase()}${word.slice(1).toLowerCase()}`)
		.join(' ');
}

