type DisplayNameError = { type: 'empty_display_name' };

export function requireDisplayName(value: string): Result<string, DisplayNameError> {
	const name = toDisplayName(value);
	return name.length > 0 ? ok(name) : err({ type: 'empty_display_name' });
}
